<?php
require __DIR__ . '/config.php';
function e($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
$months=$pdo->query("SELECT DATE_FORMAT(sale_date,'%Y-%m') AS label, ROUND(SUM(quantity*unit_price),2) AS revenue FROM sales GROUP BY DATE_FORMAT(sale_date,'%Y-%m') ORDER BY label")->fetchAll();
$categories=$pdo->query("SELECT category AS label, ROUND(SUM(quantity*unit_price),2) AS revenue FROM sales GROUP BY category ORDER BY revenue DESC")->fetchAll();
$stats=$pdo->query("SELECT COUNT(*) AS transactions, COALESCE(SUM(quantity),0) AS units, COALESCE(SUM(quantity*unit_price),0) AS revenue FROM sales")->fetch();
$search=trim($_GET['q']??'');$limit=50;
if($search!==''){$stmt=$pdo->prepare('SELECT sale_date,item_name,category,quantity,unit_price,quantity*unit_price AS total FROM sales WHERE item_name LIKE :q OR category LIKE :q2 ORDER BY sale_date DESC,id DESC LIMIT 50');$stmt->execute([':q'=>'%'.$search.'%',':q2'=>'%'.$search.'%']);}
else {$stmt=$pdo->query('SELECT sale_date,item_name,category,quantity,unit_price,quantity*unit_price AS total FROM sales ORDER BY sale_date DESC,id DESC LIMIT 50');}
$sales=$stmt->fetchAll();
$bestMonth=null;foreach($months as $m){if($bestMonth===null||(float)$m['revenue']>(float)$bestMonth['revenue'])$bestMonth=$m;}
$topCategory=$categories[0]??null;
$currency=fn($v)=>'₱'.number_format((float)$v,2);
?>
