<section id="transactions" class="panel transactions"><div class="panelhead"><div><h2>Recent transactions</h2><p>Latest 50 records · search by item or category</p></div><form method="get"><input name="q" value="<?=e($search)?>" placeholder="Search transactions..." maxlength="80"><button>Search</button></form></div><div class="scroll"><table><thead><tr><th>Date</th><th>Item</th><th>Category</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><?=e($s['sale_date'])?></td><td><b><?=e($s['item_name'])?></b></td><td><span class="pill"><?=e($s['category'])?></span></td><td><?=e($s['quantity'])?></td><td><?=e($currency($s['unit_price']))?></td><td><b><?=e($currency($s['total']))?></b></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="6">No matching transactions found.</td></tr><?php endif;?></tbody></table></div></section><footer>ShopPulse © 2026 · Academic demonstration · PHP + MySQL + Excel</footer></main></div>
